#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Fixture for tests/jd2_pre1972_sofa_oracle.rs (pre-1972 UTC, the rubber-second era).

Step 1 writes instants.csv from the fixed rules of the pre-registration in the test header.
Step 2 runs the oracle, pyerfa (ERFA, the BSD-licensed release of the SOFA routines):
erfa.dtf2d("UTC", ...), erfa.utctai and erfa.taiutc, and writes erfa.csv.

Run from the repository root (pyerfa 2.0.1.5):
    python -I tests/fixtures/jd2_pre1972_sofa_oracle/generate_jd2_pre1972_sofa_oracle.py [--instants-only]
"""
import csv
import math
import random
import sys
from pathlib import Path

import erfa

DIR = Path(__file__).resolve().parent

# The first day of each TAI-UTC expression from 1960 to 1972 (SOFA iauDat table), and the
# first day of the integer-second era, 1972-01-01.
CHANGES = [
    (1960, 1, 1), (1961, 1, 1), (1961, 8, 1), (1962, 1, 1), (1963, 11, 1), (1964, 1, 1),
    (1964, 4, 1), (1964, 9, 1), (1965, 1, 1), (1965, 3, 1), (1965, 7, 1), (1965, 9, 1),
    (1966, 1, 1), (1968, 2, 1), (1972, 1, 1),
]


def prev_day(y, m, d):
    jd1, jd2 = erfa.cal2jd(y, m, d)
    y2, m2, d2, _ = erfa.jd2cal(jd1 - 1.0, jd2)
    return int(y2), int(m2), int(d2)


def last_second(y, m, d):
    """The last valid second of 23:59 on that day, to the microsecond, below 60 + dleap."""
    jd1, jd2 = erfa.cal2jd(y, m, d)
    y2, m2, d2, _ = erfa.jd2cal(jd1 + 1.0, jd2)
    dat0 = erfa.dat(y, m, d, 0.0)
    dat12 = erfa.dat(y, m, d, 0.5)
    dat24 = erfa.dat(int(y2), int(m2), int(d2), 0.0)
    dleap = dat24 - (2.0 * dat12 - dat0)
    us = math.floor((60.0 + dleap) * 1e6 + 1e-6) - 1
    return f"{us // 1_000_000}.{us % 1_000_000:06d}"


def instants():
    rows = []
    for (y, m, d) in CHANGES:
        if (y, m, d) != (1960, 1, 1):
            py, pm, pd = prev_day(y, m, d)
            rows.append((py, pm, pd, 12, 0, "0.000000", "change"))
            rows.append((py, pm, pd, 23, 59, "59.000000", "change"))
            rows.append((py, pm, pd, 23, 59, last_second(py, pm, pd), "change"))
        rows.append((y, m, d, 0, 0, "0.000001", "change"))
    rng = random.Random(20261012)
    lo1, lo2 = erfa.cal2jd(1960, 1, 1)
    hi1, hi2 = erfa.cal2jd(1971, 12, 31)
    for _ in range(60):
        k = rng.randint(0, int(round((hi1 + hi2) - (lo1 + lo2))))
        y, m, d, _ = erfa.jd2cal(lo1, lo2 + k)
        h = rng.randint(0, 23)
        mi = rng.randint(0, 59)
        us = rng.randint(0, 59_999_999)
        rows.append((int(y), int(m), int(d), h, mi, f"{us // 1_000_000}.{us % 1_000_000:06d}", "random"))
    return rows


def main():
    step = 1 if len(sys.argv) > 1 and sys.argv[1] == "--instants-only" else 2
    rows = instants()
    with open(DIR / "instants.csv", "w", newline="") as f:
        f.write("# year,month,day,hour,minute,second,kind (generated by generate_jd2_pre1972_sofa_oracle.py)\n")
        w = csv.writer(f, lineterminator="\n")
        for r in rows:
            w.writerow(r)
    if step == 1:
        return
    with open(DIR / "erfa.csv", "w", newline="") as f:
        f.write(f"# pyerfa {erfa.__version__} (liberfa {erfa.version.erfa_version}): "
                "dtf2d(UTC) u1,u2; utctai(u1,u2) a1,a2; taiutc(a1,a2) b1,b2\n")
        w = csv.writer(f, lineterminator="\n")
        for (y, m, d, h, mi, s, _) in rows:
            u1, u2 = erfa.dtf2d("UTC", y, m, d, h, mi, float(s))
            a1, a2 = erfa.utctai(u1, u2)
            b1, b2 = erfa.taiutc(a1, a2)
            w.writerow([repr(float(x)) for x in (u1, u2, a1, a2, b1, b2)])


if __name__ == "__main__":
    main()
